script:
(function() {
  try {
    if (!document.querySelector('link[data-pr-poppins]')) {
      var pf = document.createElement('link'); pf.rel = 'stylesheet'; pf.setAttribute('data-pr-poppins', '1');
      pf.href = 'https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap';
      document.head.appendChild(pf);
    }
  } catch (e) {}
  var host = root_element.querySelector('[data-cmpn-groups]');
  var cropHost = root_element.querySelector('[data-cmpn-crops]');
  if (!host) return;
  var esc = (window.frappe && frappe.utils && frappe.utils.escape_html)
    ? frappe.utils.escape_html
    : function(s) { return (s || '').replace(/[&<>"']/g, function(c) {
        return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); };
  // [group, colour, [[href, label, subtitle, lucide inner svg]]]
  var GROUPS = [["Plan", "#3f7d3a", [["/planning_app#/dashboard", "Dashboard", "Budget, actuals and overview", "<path d=\"M3 3v18h18\"/><path d=\"M7 16v-4M12 16V8M17 16v-6\"/>"], ["/planning_app#/budget", "Budget", "Monthly crop-year budget", "<rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><path d=\"M3 9h18M3 15h18M9 3v18M15 3v18\"/>"], ["/planning_app#/forecast", "Forecast", "Weekly revisions vs actual", "<path d=\"M3 3v18h18\"/><path d=\"m19 9-5 5-4-4-3 3\"/>"], ["/planning_app#/lifetime", "Lifetime", "Budget over a planting's life", "<rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\"/><path d=\"M16 2v4M8 2v4M3 10h18\"/><path d=\"M8 14h.01M12 14h.01M16 14h.01M8 18h.01M12 18h.01\"/>"]]], ["Inputs", "#b7791f", [["/planning_app#/protocols", "Crop Protocols", "Flushes, grades and lengths", "<path d=\"M12 20h9\"/><path d=\"M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z\"/>"], ["/planning_app#/calibration", "Calibration", "Tune yields from actuals", "<circle cx=\"12\" cy=\"12\" r=\"9\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M12 3v3M12 18v3M3 12h3M18 12h3\"/>"], ["/desk/crop-cycle", "Crop Cycles", "Planting to harvest", "<path d=\"M3 12a9 9 0 0 1 9-9 9.75 9.75 0 0 1 6.74 2.74L21 8\"/><path d=\"M21 3v5h-5\"/><path d=\"M21 12a9 9 0 0 1-9 9 9.75 9.75 0 0 1-6.74-2.74L3 16\"/><path d=\"M8 16H3v5\"/>"], ["/desk/greenhouse", "Greenhouses", "Houses and areas", "<path d=\"M3 21V11l9-7 9 7v10\"/><path d=\"M3 21h18\"/><path d=\"M9 21v-6h6v6\"/>"]]], ["Classic screens", "#2f6f9f", [["/budget-forecast", "Budget & Forecast", "The classic planner", "<path d=\"M3 3v18h18\"/><path d=\"M7 16v-4M12 16V8M17 16v-6\"/>"], ["/desk/production-budget", "Budget Grid", "Classic desk budget page", "<rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><path d=\"M3 9h18M3 15h18M9 3v18M15 3v18\"/>"], ["/desk/production-projection", "Production Projection", "Annual 52-week budgets", "<rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\"/><path d=\"M16 2v4M8 2v4M3 10h18\"/><path d=\"M8 14h.01M12 14h.01M16 14h.01M8 18h.01M12 18h.01\"/>"], ["/desk/production-forecast", "Production Forecast", "Revised weeks and actuals", "<path d=\"M3 3v18h18\"/><path d=\"m19 9-5 5-4-4-3 3\"/>"]]], ["Settings", "#6b7280", [["/desk/agriculture-settings", "Agriculture Settings", "Week numbering and defaults", "<circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.68 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.68a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z\"/>"]]]];
  host.innerHTML = GROUPS.map(function(g) {
    var colour = g[1];
    var tiles = g[2].map(function(t) {
      return '<a class="cmpn-tile" href="' + esc(t[0]) + '">'
        + '<span class="cmpn-ic" style="background:' + colour + '1a;color:' + colour + '">'
        + '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'
        + t[3] + '</svg></span>'
        + '<span class="cmpn-tx"><span class="cmpn-lb">' + esc(t[1]) + '</span>'
        + '<span class="cmpn-sub">' + esc(t[2]) + '</span></span></a>';
    }).join('');
    return '<section class="cmpn-group">'
      + '<div class="cmpn-head"><span class="cmpn-dot" style="background:' + colour + '"></span>'
      + '<span class="cmpn-name">' + esc(g[0]) + '</span></div>'
      + '<div class="cmpn-grid">' + tiles + '</div></section>';
  }).join('');

  // One tile per crop, straight into /planning_app#/<crop_key>/dashboard; the page's splash shows that
  // crop's own loader while it opens (same tab).
  var FLOWER = '<path d="M12 7.5a4.5 4.5 0 1 1 4.5 4.5M12 7.5A4.5 4.5 0 1 0 7.5 12M12 7.5V9m-4.5 3a4.5 4.5 0 1 0 4.5 4.5M7.5 12H9m3 4.5a4.5 4.5 0 1 0 4.5-4.5M12 16.5V15m4.5-3H15"/><circle cx="12" cy="12" r="3"/>';
  if (cropHost && window.frappe && frappe.call) {
    frappe.call({
      method: 'frappe.client.get_list',
      args: { doctype: 'Production Crop', fields: ['name', 'crop_key', 'accent_color'], filters: { enabled: 1 }, order_by: 'sort_order asc, name asc', limit_page_length: 0 },
      callback: function(r) {
        var crops = (r && r.message) || [];
        if (!crops.length) return;
        var tiles = crops.map(function(c) {
          var colour = /^#[0-9a-f]{6}$/i.test(c.accent_color || '') ? c.accent_color : '#3f7d3a';
          return '<a class="cmpn-tile" href="/planning_app#/' + encodeURIComponent(c.crop_key) + '/dashboard">'
            + '<span class="cmpn-ic" style="background:' + colour + '1a;color:' + colour + '">'
            + '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' + FLOWER + '</svg></span>'
            + '<span class="cmpn-tx"><span class="cmpn-lb">' + esc(c.name) + '</span>'
            + '<span class="cmpn-sub">Budget &amp; forecast</span></span></a>';
        }).join('');
        cropHost.innerHTML = '<section class="cmpn-group"><div class="cmpn-head"><span class="cmpn-dot" style="background:#b8335a"></span>'
          + '<span class="cmpn-name">Crops</span></div><div class="cmpn-grid">' + tiles + '</div></section>';
      }
    });
  }
})();

style:
.cmpn{padding:4px 2px;font-family:'Poppins',var(--font-stack),'Inter',sans-serif;}
.cmpn-title{font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:#8a8f98;font-weight:600;margin:0 0 12px 2px;}
.cmpn-group{padding:0 0 18px;}
.cmpn-group:last-child{padding-bottom:4px;}
.cmpn-head{display:flex;align-items:center;gap:9px;margin:0 0 9px 2px;}
.cmpn-dot{width:10px;height:10px;border-radius:50%;flex:0 0 auto;}
.cmpn-name{font-size:14px;font-weight:600;letter-spacing:-.01em;}
.cmpn-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:10px;}
.cmpn-tile{display:flex;align-items:center;gap:11px;padding:13px 15px;border:1px solid var(--border-color,#e2e4e9);border-radius:10px;background:var(--card-bg,#fff);text-decoration:none;color:inherit;transition:box-shadow .18s ease,transform .18s ease;}
.cmpn-tile:hover{box-shadow:0 2px 6px rgba(0,0,0,.06);transform:translateY(-1px);text-decoration:none;}
.cmpn-ic{width:36px;height:36px;border-radius:9px;display:flex;align-items:center;justify-content:center;flex:0 0 auto;}
.cmpn-ic svg{width:18px;height:18px;}
.cmpn-tx{display:flex;flex-direction:column;min-width:0;}
.cmpn-lb{font-size:13px;font-weight:600;letter-spacing:-.01em;}
.cmpn-sub{font-size:11px;color:#8a8f98;margin-top:1px;}
